mapper.select:
SELECT d.* FROM iot_device d INNER JOIN iot_device_group_relation r ON d.id = r.device_id WHERE r.group_id = #{groupId} AND r.del_flag = '0' AND d.del_flag = '0'
AND d.device_name LIKE CONCAT('%', #{device.deviceName}, '%')
AND d.device_code = #{device.deviceCode}
AND d.product_id = #{device.productId}
AND d.status = #{device.status}
ORDER BY d.create_time DESC
